/*
 * A341006  Numbers whose sum of even digits and sum of odd digits differ by
 *          5.
 * https://oeis.org/A341006
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn
 * Formula:   not stated
 * Range:     u8 n <= 21, u16 n <= 4031, u32 n <= 5001, u64 n <= 5001,
 *            u128 n <= 5001, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A341006: generated by brute‑force search of integers whose sum of even digits
   and sum of odd digits differ by 5. */

#include <stdlib.h>
#include <stdint.h>

seq_t a(idx_t n)
{
    /* static cache for the sequence terms */
    static seq_t *cache = NULL;    /* array of found terms */
    static size_t cache_cap = 0;   /* capacity of the array */
    static size_t cache_len = 0;   /* number of terms stored */
    static idx_t next_candidate = 1;   /* next integer to test */

    if (cache_len < n) {
        /* enlarge cache if necessary */
        if (cache_len == cache_cap || cache_cap == 0) {
            size_t new_cap = (cache_cap == 0) ? 64 : cache_cap << 1;
            seq_t *tmp = (seq_t *)realloc(cache, sizeof(seq_t) * new_cap);
            if (!tmp) return 0;          /* allocation failed – return 0 */
            cache = tmp;
            cache_cap = new_cap;
        }

        /* generate terms until we have at least n of them */
        while (cache_len < n) {
            idx_t cand = next_candidate++;
            idx_t t = cand;
            idx_t sum_even = 0;
            idx_t sum_odd  = 0;

            if (t == 0) {
                /* digits of 0 are 0 – even */
                sum_even = 0;
            } else {
                while (t > 0) {
                    unsigned d = (unsigned)(t % 10);
                    t /= 10;
                    if (d & 1)
                        sum_odd += d;
                    else
                        sum_even += d;
                }
            }

            idx_t diff = (sum_even >= sum_odd) ? (sum_even - sum_odd) : (sum_odd - sum_even);

            if (diff == (idx_t)5) {
                /* store the term (might overflow if seq_t cannot hold the value) */
                cache[cache_len++] = (seq_t)cand;
            }
        }
    }

    return cache[n - 1];
}
